public class NebulaRPCInvoker
{

    Action<MessageWriter> sender;
    Action localBodyProcess;
    int hash;
    public bool IsDummy { get; private set; }

    public NebulaRPCInvoker(int hash, Action<MessageWriter> sender, Action localBodyProcess)
    {
        this.hash = hash;
        this.sender = sender;
        this.localBodyProcess = localBodyProcess;
        this.IsDummy = false;
    }

    public NebulaRPCInvoker(Action localAction)
    {
        this.hash = 0;
        this.sender = null!;
        this.localBodyProcess = localAction;
        this.IsDummy = true;
    }

    public void Invoke(MessageWriter writer)
    {
        writer.Write(hash);
        sender.Invoke(writer);
        localBodyProcess.Invoke();
    }

    /// <summary>
    /// RPCプロセスやダミーのRPCプロセスを送信します。
    /// 送信のタイミングはRouterの都合に準じます。
    /// </summary>
    public void InvokeSingle()
    {
        if (IsDummy)
            RPCRouter.SendDummy(localBodyProcess);
        else
            RPCRouter.SendRpc("Invoker", hash, (writer) => sender.Invoke(writer), () => localBodyProcess.Invoke(), true);
    }

    /// <summary>
    /// Routerの都合を無視して、プロセスをローカルでのみ実行します。
    /// </summary>
    public void InvokeLocal()
    {
        localBodyProcess.Invoke();
    }
}

public static class RPCRouter
{
    public class RPCSection : IDisposable
    {
        public string Name;
        private WinCheckBlocker.WinCheckSection? checkWinningBlocker = null;
        public void Dispose()
        {
            if (currentSection != this) return;

            currentSection = null;
            //NebulaPlugin.Log.Print(NebulaLog.LogLevel.Log, $"End Evacuating Rpcs ({Name}, Size = {evacuateds.Count})");

            var rpcArray = evacuateds.ToArray();
            evacuateds.Clear();
            CombinedRemoteProcess.CombinedRPC.Invoke(checkWinningBlocker != null, rpcArray);

            checkWinningBlocker?.Dispose();
        }

        public RPCSection(string? name = null, bool blockCheckWinning = false)
        {
            Name = name ?? "Untitled";
            if (currentSection == null)
            {
                currentSection = this;
                //NebulaPlugin.Log.Print(NebulaLog.LogLevel.Log,  $"Start Evacuating Rpcs ({Name})");
            }else {
                //NebulaPlugin.Log.Print(NebulaLog.LogLevel.Log, $"Rpc section \"{Name}\" is in \"{currentSection.Name}\"! It is ignored.");
            }

            if (blockCheckWinning && currentSection.checkWinningBlocker == null) currentSection.checkWinningBlocker = WinCheckBlocker.CreateSection(name);
        }
    }

    static public RPCSection CreateSection(string? label = null, bool blockCheckWinning = false) => new RPCSection(label, blockCheckWinning);

    static RPCSection? currentSection = null;
    static List<NebulaRPCInvoker> evacuateds = new();

    public static void SendDummy(Action localProcess)
    {
        if (currentSection == null) localProcess.Invoke();
        else
        {
            evacuateds.Add(new(localProcess));
        }
    }

    public static void SendRpc(string name, int hash, Action<MessageWriter> sender, Action localBodyProcess, bool shouldBeReliable) {
        if(currentSection == null)
        {
            var origWriter = AmongUsLLImpl.AmongUsClientInstance.StartRpcImmediately(AmongUsLLImpl.LocalPlayer.NetId, 128, shouldBeReliable ? Hazel.SendOption.Reliable : Hazel.SendOption.None, -1);
            var virialWriter = MessageWriter.Get();
            virialWriter.Write(hash);
            sender.Invoke(virialWriter);
            virialWriter.End(origWriter);
            AmongUsLLImpl.AmongUsClientInstance.FinishRpcImmediately(origWriter);

            try
            {
                localBodyProcess.Invoke();
            }
            catch(Exception ex)
            {
                //NebulaPlugin.Log.PrintWithBepInEx(NebulaLog.LogLevel.Error, NebulaLog.LogCategory.System, $"Error in RPC(Invoke: {name})\n" + ex.ToString());
            }

            //NebulaPlugin.Log.PrintWithBepInEx(NebulaLog.LogLevel.Log, null, $"Called RPC : {name}");
        }
        else
        {
            evacuateds.Add(new(hash, sender, localBodyProcess));

            //NebulaPlugin.Log.Print(NebulaLog.LogLevel.Log, $"Evacuated RPC : {name} (by {currentSection!.Name})");
        }
    }
}

[NebulaPreprocess(PreprocessPhase.FixStructure)]
public class RemoteProcessBase
{
    static public Dictionary<int, RemoteProcessBase> AllNebulaProcess = new();


    public int Hash { get; private set; } = -1;
    public string Name { get; private set; }
    public bool ShouldBeReliable { get; private init; } = true;

    public RemoteProcessBase(string name, bool shouldBeReliable)
    {
        Hash = name.ComputeConstantHash();
        Name = name;

        if (AllNebulaProcess.ContainsKey(Hash)) NebulaLogger.Instance.Error(name + " is duplicated. (" + Hash + ")");
        else NebulaLogger.Instance.Message(name + " is registered. (" + Hash + ")");

        AllNebulaProcess[Hash] = this;
        ShouldBeReliable = shouldBeReliable;
    }

    static Dictionary<string, RemoteProcess<object[]>> harmonyRpcMap = new();
    static private void WrapRpcMethod(Harmony harmony, MethodInfo method)
    {
        //元の静的メソッドをコピーしておく
        var copiedOriginal = harmony.Patch(method);

        //メソッド呼び出しのパラメータを取得
        var parameters = method.GetParameters();

        //RPCを定義し、登録

        List<(Action<MessageWriter, object> writer, Func<MessageReader, object> reader)> processList = new();
        if (!method.IsStatic) processList.Add(RemoteProcessAsset.GetProcess(method.DeclaringType!));
        processList.AddRange(parameters.Select(p => RemoteProcessAsset.GetProcess(p.ParameterType)));

        RemoteProcess<object[]> rpc = new(method.DeclaringType!.FullName + "." + method.Name,
            (writer, args) =>
            {
                for (int i = 0; i < processList.Count; i++) processList[i].writer(writer, args[i]);
            },
            (reader) =>
            {
                return processList.Select(p => p.reader(reader)).ToArray();
            },
            (args, _) =>
            {
                copiedOriginal.Invoke(null, args);
            }
            );
        harmonyRpcMap[method.DeclaringType!.FullName + "." + method.Name] = rpc;

        //静的メソッドをRPC呼び出しに変更
        static bool RpcPrefix(object? __instance, object[] __args, MethodBase __originalMethod)
        {
            var name = __originalMethod.DeclaringType!.FullName + "." + __originalMethod.Name;
            if (!__originalMethod.IsStatic) __args = __args.Prepend(__instance!).ToArray();
            harmonyRpcMap[name].Invoke(__args);
            return false;
        }

        var prefixInfo = RpcPrefix;

        var newMethod = harmony.Patch(method, new HarmonyMethod(prefixInfo.Method));
    }

    static IEnumerator Preprocess(NebulaPreprocessor preprocessor)
    {
        yield return preprocessor.SetLoadingText("Building Remote Procedure Calls");

        var types = Assembly.GetAssembly(typeof(RemoteProcessBase))?.GetTypes().Where((type) => type.IsDefined(typeof(NebulaRPCHolder)));
        if (types == null) yield break;

        foreach (var type in types)
        {
            Helpers.RunStaticConstructor(type);
            foreach(var method in type.GetMethods().Where(m => m.IsDefined(typeof(NebulaRPC)))) WrapRpcMethod(NebulaPlugin.Harmony, method);
        }

        //全アドオンに対してRPCをセットアップ
        foreach (var script in AddonScriptManager.ScriptAssemblies)
        {
            foreach (var t in script.Assembly.GetTypes())
            {
                Helpers.RunStaticConstructor(t);
                foreach (var method in t.GetMethods().Where(m => m.IsDefined(typeof(NebulaRPC))))
                {
                    //RPCを持つならハンドシェイクが必要
                    script.Addon.MarkAsNeedingHandshake();
                    WrapRpcMethod(NebulaPlugin.Harmony, method);
                }
            }
        }
    }

    public virtual void Receive(MessageReader reader) { }
}

public abstract class RemoteProcessArgumentBase
{
    internal abstract object ReadDynamic(MessageReader reader);
    internal abstract void WriteDynamic(MessageWriter writer, object obj);

    private static Dictionary<Type, RemoteProcessArgumentBase> dynamicProcessDic = [];
    internal static RemoteProcessArgumentBase? Get(Type type) {
        if (!dynamicProcessDic.ContainsKey(type)) Helpers.RunStaticConstructor(type);
        return dynamicProcessDic.TryGetValue(type, out var val) ? val : null;
    }
    protected void Register(Type type, RemoteProcessArgumentBase process) => dynamicProcessDic[type] = process;

    static RemoteProcessArgumentBase()
    {
        new RemoteProcessArgument<byte>((writer, val) => writer.Write(val), reader => reader.ReadByte());

        new RemoteProcessArgument<short>((writer, val) => writer.Write(val), reader => reader.ReadInt16());
        new RemoteProcessArgument<ushort>((writer, val) => writer.Write(val), reader => reader.ReadUInt16());
        new RemoteProcessArgument<int>((writer, val) => writer.Write(val), reader => reader.ReadInt32());
        new RemoteProcessArgument<uint>((writer, val) => writer.Write(val), reader => reader.ReadUInt32());
        new RemoteProcessArgument<ulong>((writer, val) => writer.Write(val), reader => reader.ReadUInt64());

        new RemoteProcessArgument<float>((writer, val) => writer.Write(val), reader => reader.ReadSingle());
        new RemoteProcessArgument<bool>((writer, val) => writer.Write(val), reader => reader.ReadBoolean());
        new RemoteProcessArgument<string>((writer, val) => writer.Write(val), reader => reader.ReadString());

        new RemoteProcessArgument<Vector2>((writer, vec) =>
        {
            writer.Write(vec.x);
            writer.Write(vec.y);
        }, reader => new(reader.ReadSingle(), reader.ReadSingle()));
        new RemoteProcessArgument<Vector3>((writer, vec) =>
        {
            writer.Write(vec.x);
            writer.Write(vec.y);
            writer.Write(vec.z);
        }, reader => new(reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle()));
        new RemoteProcessArgument<Vector4>((writer, vec) =>
        {
            writer.Write(vec.x);
            writer.Write(vec.y);
            writer.Write(vec.z);
            writer.Write(vec.w);
        }, reader => new(reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle()));

        new RemoteProcessArgument<VVector2>((writer, vec) =>
        {
            writer.Write(vec.x);
            writer.Write(vec.y);
        }, reader => new(reader.ReadSingle(), reader.ReadSingle()));
        new RemoteProcessArgument<VVector3>((writer, vec) =>
        {
            writer.Write(vec.x);
            writer.Write(vec.y);
            writer.Write(vec.z);
        }, reader => new(reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle()));
        new RemoteProcessArgument<VVector4>((writer, vec) =>
        {
            writer.Write(vec.x);
            writer.Write(vec.y);
            writer.Write(vec.z);
            writer.Write(vec.w);
        }, reader => new(reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle()));
        new RemoteProcessArgument<VColor>((writer, vec) =>
        {
            writer.Write(vec.R);
            writer.Write(vec.G);
            writer.Write(vec.B);
            writer.Write(vec.A);
        }, reader => new(reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle()));

        new RemoteProcessArgument<OutfitCandidate>((writer, outfit) =>
        {
            writer.Write(outfit.Outfit.Id.ownerId);
            writer.Write(outfit.Outfit.Id.outfitId);
            writer.Write(outfit.Tag);
            writer.Write(outfit.Priority);
            writer.Write(outfit.SelfAware);
            writer.Write(outfit.IgnoreMask?.AsRawPattern ?? 0u);
        }, reader => {
            OutfitDefinition? outfit = null;
            NebulaGameManager.Instance?.TryGetOutfit(new(reader.ReadInt32(), reader.ReadInt32()), out outfit);
            return new OutfitCandidate(outfit!, reader.ReadString(), reader.ReadInt32(), reader.ReadBoolean(), BitMasks.AsPlayer(reader.ReadUInt32()));
        });

        new RemoteProcessArgument<TimeLimitedModulator>((writer, mod) =>
        {
            writer.Write(mod.Timer);
            writer.Write(mod.CanPassMeeting);
            writer.Write(mod.Priority);
            writer.Write(mod.DuplicateTag);

            if (mod is SpeedModulator sm)
            {
                writer.Write(1);
                writer.Write(sm.Num);
                writer.Write(sm.DirectionalNum.x);
                writer.Write(sm.DirectionalNum.y);
                writer.Write(sm.DirectionalNum.z);
                writer.Write(sm.DirectionalNum.w);
                writer.Write(sm.IsMultiplier);
                writer.Write(sm.CanBeAware);
            }
            else if (mod is SizeModulator sim)
            {
                writer.Write(2);
                writer.Write(sim.Size.x);
                writer.Write(sim.Size.y);
                writer.Write(sim.CanBeAware);
                writer.Write(sim.Smooth);
            }
            else if (mod is FloatModulator fm)
            {
                writer.Write(4);
                writer.Write(fm.Attribute.Id);
                writer.Write(fm.Num);
                writer.Write(fm.CanBeAware);
            }
            else if (mod is AttributeModulator am)
            {
                writer.Write(3);
                writer.Write(am.Attribute.Id);
                writer.Write(am.CanBeAware);
            }
        }, reader => {
            float timer = reader.ReadSingle();
            bool canPassMeeting = reader.ReadBoolean();
            int priority = reader.ReadInt32();
            string dupTag = reader.ReadString();
            int type = reader.ReadInt32();

            if (type == 1)
                return new SpeedModulator(reader.ReadSingle(), new VVector4(reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle(), reader.ReadSingle()), reader.ReadBoolean(), timer, canPassMeeting, priority, dupTag, reader.ReadBoolean());
            else if (type == 2)
                return new SizeModulator(new(reader.ReadSingle(), reader.ReadSingle()), timer, canPassMeeting, priority, dupTag, reader.ReadBoolean(), reader.ReadBoolean());
            else if (type == 3)
                return new AttributeModulator(PlayerAttributeImpl.GetAttributeById(reader.ReadInt32()), timer, canPassMeeting, priority, dupTag, reader.ReadBoolean());
            else if (type == 4)
                return new FloatModulator(PlayerAttributeImpl.GetAttributeById(reader.ReadInt32()), reader.ReadSingle(), timer, canPassMeeting, priority, dupTag, reader.ReadBoolean());

            return null!;
        });

        new RemoteProcessArgument<TranslatableTag>((writer, tag) => writer.Write(tag?.Id ?? int.MaxValue), reader => TranslatableTag.ValueOf(reader.ReadInt32())!);
        new RemoteProcessArgument<CommunicableTextTag>((writer, tag) => writer.Write(tag?.Id ?? int.MaxValue), reader => TranslatableTag.ValueOf(reader.ReadInt32())!);

        new RemoteProcessArgument<PlayerModInfo>((writer, player) => writer.Write(player?.PlayerId ?? byte.MaxValue), reader => (PlayerModInfo)NebulaGameManager.Instance?.GetPlayer(reader.ReadByte())!);
        new RemoteProcessArgument<GamePlayer>((writer, player) => writer.Write(player?.PlayerId ?? byte.MaxValue), reader => NebulaGameManager.Instance?.GetPlayer(reader.ReadByte())!);
        new RemoteProcessArgument<IPlayerlike>((writer, player) => writer.Write(player?.PlayerlikeId ?? int.MaxValue), reader => NebulaGameManager.Instance?.GetPlayerlike(reader.ReadInt32())!);
        new RemoteProcessArgument<Virial.Game.DeadBody>((writer, deadBody) => writer.Write(deadBody?.Id ?? -1), reader => ModSingleton<DeadBodyManager>.Instance.TryGetDeadBody(reader.ReadInt32(), out var d) ? d : null!);

        new RemoteProcessArgument<INebulaAchievement>((writer, achievement) => writer.Write((ulong)achievement!.Id.ComputeConstantLongHash()), (reader) => (NebulaAchievementManager.TryGetAchievement((long)reader.ReadUInt64(), out var ach) ? ach : null)!);

        new RemoteProcessArgument<DefinedAssignable>((writer, role) => { 
            writer.Write(role switch { DefinedRole => (byte)0, DefinedModifier => (byte)1, DefinedGhostRole => (byte)2, _ => byte.MaxValue });
            writer.Write(role?.Id ?? -1); 
        }, reader =>
        {
            var b = reader.ReadByte();
            var id = reader.ReadInt32();
            switch (b)
            {
                case 0:
                    return Roles.Roles.GetRole(id)!;
                case 1:
                    return Roles.Roles.GetModifier(id)!;
                case 2:
                    return Roles.Roles.GetGhostRole(id)!;
                default:
                    return null!;
            }
        });
        new RemoteProcessArgument<DefinedRole>((writer, role) => writer.Write(role?.Id ?? -1), reader => Roles.Roles.GetRole(reader.ReadInt32())!);
        new RemoteProcessArgument<DefinedGhostRole>((writer, role) => writer.Write(role?.Id ?? -1), reader => Roles.Roles.GetGhostRole(reader.ReadInt32())!);
        new RemoteProcessArgument<DefinedModifier>((writer, role) => writer.Write(role?.Id ?? -1), reader => Roles.Roles.GetModifier(reader.ReadInt32())!);

        new RemoteProcessArgument<PlayerControl>((writer, player) => writer.Write(player.AsBoolFast() ? player!.PlayerId : byte.MaxValue), reader => Helpers.GetPlayer(reader.ReadByte())!);
    }
}
public class RemoteProcessArgument<T> : RemoteProcessArgumentBase
{
    internal Action<MessageWriter, T?> Writer { get; private init; }
    internal Func<MessageReader, T> Reader { get; private init; }
    internal RemoteProcessArgument(Action<MessageWriter, T?> writer, Func<MessageReader, T> reader)
    {
        this.Writer = writer;
        this.Reader = reader;
        Protocol = this;
        Register(typeof(T), this);
    }

    override internal object ReadDynamic(MessageReader reader) => Reader.Invoke(reader)!;
    override internal void WriteDynamic(MessageWriter writer, object obj) => Writer.Invoke(writer, (T)obj);

    static private RemoteProcessArgument<T>? Protocol { get; set; }
    static public T Read(MessageReader reader) => Protocol!.Reader.Invoke(reader);
    static public void Write(MessageWriter writer, T? obj) => Protocol!.Writer.Invoke(writer, obj);

}

